select aj1_0.id,coalesce(te1_1.id,e1_0.id),case when te1_1.id is not null then te1_1.episode_no else e1_0.episode_no end,case when te1_1.id is not null then te1_1.title else e1_0.title end,case when te1_1.id is not null then te1_1.status else e1_0.status end,case when te1_1.id is not null then te1_1.updated_at else e1_0.updated_at end from analysis_jobs aj1_0 left join analysis_job_episode_targets te1_0 on aj1_0.id=te1_0.analysis_job_id left join episodes te1_1 on te1_1.id=te1_0.episode_id left join episodes e1_0 on e1_0.id=aj1_0.episode_id where aj1_0.work_id='082683aa-c3d8-56b3-91e2-8031e85f4a92' and aj1_0.id in ('55e35eff-e5fd-5dfb-8432-496e5ba8b072') and ((te1_1.id is not null and te1_1.work_id='082683aa-c3d8-56b3-91e2-8031e85f4a92') or (te1_1.id is null and e1_0.work_id='082683aa-c3d8-56b3-91e2-8031e85f4a92')) order by aj1_0.id,coalesce(te1_1.episode_no,e1_0.episode_no),coalesce(te1_1.id,e1_0.id);
